insert into public.seguindo (seguidor, seguido)
select d.id, s.id from auth.users d cross join auth.users s
where d.email like '%@demo.checkpoint' and s.email not like '%@demo.checkpoint'
on conflict do nothing;

insert into public.seguindo (seguidor, seguido)
select a.id, b.id from auth.users a join auth.users b on a.id <> b.id
where a.email like '%@demo.checkpoint' and b.email like '%@demo.checkpoint'
on conflict do nothing;

commit;
